hooks.command:
python3 -c "
import sys, json, subprocess
try:
    d = json.load(sys.stdin)
    f = d.get('file_path', '')
    if f.endswith('.kt') and 'src/main' in f:
        r = subprocess.run(['./gradlew', 'compileKotlin', '--quiet'], cwd='backend', capture_output=True, text=True, timeout=120)
        if r.returncode != 0:
            print('COMPILE ERROR (fix before continuing):')
            print(r.stdout or r.stderr)
            sys.exit(1)
    elif f.endswith(('.ts', '.tsx')):
        subprocess.run(['npx', 'prettier', '--write', f], capture_output=True)
except Exception as e:
    pass
"
